/**
 * Custom characters: a silhouette of the user's own (generated by their agent or imported from an SVG) that a bot
 * wears instead of one of the built-in shapes, with AppuBot's own glossy body, dark visor and eyes on it. The library
 * lives on the computer (`<dataDir>/characters.json`), shared by every bot; a bot points at one with `characterId`.
 * The drawing rules (sanitizing, normalizing, where the face goes, SVG import) are chat-core's `characters.ts`.
 */
import { z } from 'zod';
import { Id, Timestamp } from './entities';

/** A character's name: at most this many characters, one line. */
export const CHARACTER_NAME_MAX = 40;
/** A stored body (normalized path data, chat-core's own serialization): at most this many characters. */
export const CHARACTER_BODY_MAX = 12_000;
/** How many characters the library keeps. */
export const CHARACTERS_MAX = 100;
/** What a description for `characters.generate` may run to. */
export const CHARACTER_PROMPT_MAX = 300;

/**
 * Where AppuBot's visor sits on the body (its centre, in the 100×100 box) and how big it is there (`s` 1: 56 wide,
 * 26 tall, as on the round bot).
 */
export const CharacterFaceSchema = z.object({
  x: z.number().min(0).max(100).default(50),
  y: z.number().min(0).max(100),
  s: z.number().min(0.2).max(1.2),
});
export type CharacterFace = z.infer<typeof CharacterFaceSchema>;

/**
 * Only path commands, numbers and separators (chat-core writes M, L, C, Q, Z with plain decimals): what reaches an
 * SVG `d` attribute anywhere (the apps, the agent cursor, Telegram's photo) can never carry anything else.
 */
export const CHARACTER_BODY_CHARS = /^[MLCQZ0-9 .-]+$/;

export const CharacterSchema = z.object({
  id: Id,
  name: z.string().min(1).max(CHARACTER_NAME_MAX),
  /** one path in the 100×100 box (fill-rule nonzero), normalized into about 6..94 */
  body: z.string().min(1).max(CHARACTER_BODY_MAX).regex(CHARACTER_BODY_CHARS),
  face: CharacterFaceSchema,
  source: z.enum(['generated', 'imported']),
  createdAt: Timestamp,
});
export type Character = z.infer<typeof CharacterSchema>;

/** A character before it is saved: a generated candidate, or what an imported SVG turned into. */
export const CharacterDraftSchema = CharacterSchema.pick({ name: true, body: true, face: true });
export type CharacterDraft = z.infer<typeof CharacterDraftSchema>;
